/* Japan fungi dashboard for /kinokomon/ and /ja/kinokomon/.
 * Renders /assets/data/shroomhunt/dashboard.json and, for the map drill-down, the per-area files under
 * /assets/data/shroomhunt/areas/. Both are regenerated by the ShroomHunt repo and arrive as pull requests.
 * Pure helpers are exported for tests/fungi_dashboard.test.js.
 */
(function (root) {
  'use strict';

  var JAPAN_BOX = { lonMin: 122, lonMax: 154, latMin: 24, latMax: 46, refLat: 35 };
  var MESH_DLAT = 5 / 60;      // JIS 2nd mesh: 5 minutes of latitude
  var MESH_DLON = 7.5 / 60;    // and 7.5 minutes of longitude (about 10 km square)
  var MIN_SPAN = 1.2;          // degrees: smallest zoom window

  var LABELS = {
    PRESERVED_SPECIMEN: ['Preserved specimen', '標本'],
    MATERIAL_SAMPLE: ['DNA / sample', '試料・DNA'],
    HUMAN_OBSERVATION: ['Field observation', '観察記録'],
    LIVING_SPECIMEN: ['Living culture', '生体・培養株'],
    OCCURRENCE: ['Other occurrence', 'その他の記録'],
    MATERIAL_CITATION: ['Literature citation', '文献記録'],
    OBSERVATION: ['Observation', '観察'],
    MACHINE_OBSERVATION: ['Machine observation', '機械観測'],
    FOSSIL_SPECIMEN: ['Fossil', '化石'],
    species: ['To species', '種まで同定'],
    genus: ['To genus only', '属まで'],
    higher: ['Family or above', '科以上'],
    Unknown: ['Unknown', '不明']
  };
  var TRIAGE = {
    'Japanese genus-only records exist: check them': ['Check Japanese genus-only records', '国内の属止まり記録を確認'],
    'genus unrecorded in Japan': ['Genus also unrecorded in Japan', '属も国内未記録'],
    'genus known in Japan': ['Genus known in Japan', '属は国内記録あり']
  };
  var MONTHS_EN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function fmtInt(n) { return Number(n || 0).toLocaleString('en-US'); }
  function pct(a, b) { if (!b) return '–'; return Math.round((100 * a) / b) + '%'; }
  function humanize(key) {
    var s = String(key).toLowerCase().replace(/_/g, ' ');
    return s.charAt(0).toUpperCase() + s.slice(1);
  }
  function label(key, lang) {
    var pair = LABELS[key];
    if (!pair) return humanize(key);
    return lang === 'ja' ? pair[1] : pair[0];
  }
  function triage(hint, lang) {
    var pair = TRIAGE[hint];
    if (!pair) return hint;
    return lang === 'ja' ? pair[1] : pair[0];
  }
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function monthName(i, lang) { return lang === 'ja' ? i + '月' : MONTHS_EN[i - 1]; }

  // ---- projection: equirectangular with longitudes shrunk by cos(reference latitude)
  function lonScale(box) { return Math.cos((((box || JAPAN_BOX).refLat) * Math.PI) / 180); }
  function mapSize(width, box) {
    box = box || JAPAN_BOX;
    var s = width / ((box.lonMax - box.lonMin) * lonScale(box));
    return { width: width, height: Math.round((box.latMax - box.latMin) * s), scale: s };
  }
  function project(lat, lon, width, height, box) {
    box = box || JAPAN_BOX;
    return {
      x: ((lon - box.lonMin) / (box.lonMax - box.lonMin)) * width,
      y: ((box.latMax - lat) / (box.latMax - box.latMin)) * height
    };
  }
  function unproject(x, y, width, height, box) {
    return {
      lat: box.latMax - (y / height) * (box.latMax - box.latMin),
      lon: box.lonMin + (x / width) * (box.lonMax - box.lonMin)
    };
  }
  // bbox = [latMin, latMax, lonMin, lonMax] -> padded box at least MIN_SPAN degrees each way
  function zoomBox(bbox) {
    var cy = (bbox[0] + bbox[1]) / 2, cx = (bbox[2] + bbox[3]) / 2;
    var h = Math.max(MIN_SPAN, (bbox[1] - bbox[0]) * 1.25), w = Math.max(MIN_SPAN, (bbox[3] - bbox[2]) * 1.25);
    return { latMin: cy - h / 2, latMax: cy + h / 2, lonMin: cx - w / 2, lonMax: cx + w / 2, refLat: cy };
  }
  function bucket(n) {
    if (n < 10) return 0;
    if (n < 100) return 1;
    if (n < 1000) return 2;
    if (n < 10000) return 3;
    return 4;
  }
  // A square's key is its JIS 2nd-mesh row and column: floor(lat / 5') and floor(lon / 7.5').
  function meshKey(lat, lon) {
    return Math.floor(lat / MESH_DLAT + 1e-9) + ':' + Math.floor(lon / MESH_DLON + 1e-9);
  }
  // Which drill-down area is under a point: a curated island first, then the area of the ~10 km square.
  function areaAt(lat, lon, index) {
    var hit = null;
    (index.areas || []).forEach(function (a) {
      var b = a.bbox;
      if (!hit && a.kind === 'island' && lat >= b[0] && lat <= b[1] && lon >= b[2] && lon <= b[3]) hit = a.id;
    });
    return hit || (index.cells && index.cells[meshKey(lat, lon)]) || null;
  }
  function filterSpecies(list, kind, month) {
    return list.filter(function (s) {
      return (kind === 'all' || s.k === kind) && (!month || (s.m && s.m[month - 1] > 0));
    });
  }
  // One locality holding 30%+ of an area's records means the list reflects a survey site, not the area.
  function samplingNote(top, total) {
    if (!top || !top.length || !total) return null;
    var share = Math.round((100 * top[0][1]) / total);
    return share >= 30 ? { name: top[0][0], share: share } : null;
  }
  function isValid(d) {
    return !!(d && d.totals && typeof d.totals.records === 'number' &&
      Array.isArray(d.mesh) && Array.isArray(d.leads) && Array.isArray(d.sources));
  }

  var api = {
    JAPAN_BOX: JAPAN_BOX, fmtInt: fmtInt, pct: pct, label: label, triage: triage, esc: esc,
    mapSize: mapSize, project: project, zoomBox: zoomBox, bucket: bucket, meshKey: meshKey, areaAt: areaAt,
    filterSpecies: filterSpecies, samplingNote: samplingNote, monthName: monthName, isValid: isValid
  };
  if (typeof module === 'object' && module.exports) { module.exports = api; return; }

  /* ---------------------------------------------------------------- browser rendering */
  var doc = root.document;
  var lang = (doc.documentElement.getAttribute('lang') || 'en').indexOf('ja') === 0 ? 'ja' : 'en';
  var T = {
    records: ['records', '件'],
    species: ['species', '種'],
    square: ['~10 km square', '約10km四方'],
    loadError: ['The dashboard data could not be loaded.', 'ダッシュボードのデータを読み込めませんでした。'],
    areaError: ['This area could not be loaded.', 'この地域のデータを読み込めませんでした。'],
    downloaded: ['downloaded', '取得日'],
    clickHint: ['Click', 'クリック'],
    squares: ['squares', '区画'],
    byName: ['matched by place name', '地名で照合'],
    unresolved: ['not identified to species', '種まで未同定'],
    sampling: ['Most records come from one survey site', '記録の多くが1か所の調査地に集中しています'],
    noSpecies: ['No species match these filters.', '条件に合う種はありません。'],
    noPossible: ['No nearby candidates of this kind.', 'この種類の候補はありません。'],
    km: ['km', 'km'],
    islands: ['Islands', '島'],
    where: ['Where / habitat', '場所・生息環境'],
    nearest: ['Nearest record', '最寄りの記録'],
    likelihood: ['Likelihood', '可能性'],
    months: ['Months found', '記録された月'],
    family: ['Family', '科'],
    sp: ['Species', '種'],
    rec: ['Records', '記録数'],
    evidence: ['Evidence', '証拠'],
    ev_s: ['specimen', '標本'], ev_d: ['DNA', 'DNA'], ev_o: ['sighting', '観察']
  };
  function t(k) { return lang === 'ja' ? T[k][1] : T[k][0]; }
  function $(id) { return doc.getElementById(id); }

  var state = { d: null, index: null, area: null, kind: 'm', month: 0, box: JAPAN_BOX, cache: {} };

  function barRows(rows, total, fmt) {
    var max = rows.reduce(function (m, r) { return Math.max(m, r[1]); }, 0) || 1;
    return rows.map(function (r) {
      return '<div class="fd-bar"><span class="fd-bar__label">' + esc(fmt ? fmt(r[0]) : r[0]) + '</span>' +
        '<span class="fd-bar__track"><span class="fd-bar__fill" style="width:' + ((100 * r[1]) / max).toFixed(1) + '%"></span></span>' +
        '<span class="fd-bar__value">' + fmtInt(r[1]) + (total ? ' <small>' + pct(r[1], total) + '</small>' : '') + '</span></div>';
    }).join('');
  }

  function renderKpis(d) {
    var tot = d.totals;
    var k = [
      [fmtInt(tot.records), lang === 'ja' ? '国内の菌類記録' : 'fungus records from Japan'],
      [fmtInt(tot.species), lang === 'ja' ? '記録された種' : 'species recorded'],
      [pct(tot.to_species, tot.records), lang === 'ja' ? '種まで同定済み' : 'identified to species'],
      [pct(tot.georeferenced, tot.records), lang === 'ja' ? '座標付き' : 'have map coordinates'],
      [fmtInt(d.lead_totals.with_mo), lang === 'ja' ? '近隣国のみで記録（要調査）' : 'leads: recorded next door, not in Japan']
    ];
    $('fd-kpis').innerHTML = k.map(function (x) {
      return '<div class="fd-kpi"><div class="fd-kpi__value">' + esc(x[0]) + '</div><div class="fd-kpi__label">' + esc(x[1]) + '</div></div>';
    }).join('');
  }

  /* ---------------------------------------------------------------- map */
  var map = { draw: null };
  function setupMap(d) {
    var fig = $('fd-map'), svg = fig.querySelector('svg'), tip = fig.querySelector('.fd-map__tip');
    var cells = {};
    d.mesh.forEach(function (m) { cells[meshKey(m[0], m[1])] = m; });
    var geom = null;
    function draw() {
      var box = state.box;
      var W = Math.max(280, fig.clientWidth), H = Math.max(280, fig.clientHeight);
      var size = mapSize(W, box);
      if (size.height > H) size = { width: Math.round(W * H / size.height), height: H };
      var ox = (W - size.width) / 2, oy = (H - size.height) / 2;
      geom = { box: box, size: size, ox: ox, oy: oy };
      svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
      var zoomed = box !== JAPAN_BOX;
      var paths = ['', '', '', '', ''], sel = '';
      var selCells = state.index && state.area ? state.index.cells : null;
      var selIds = state.area ? (state.area.members || [state.area.id]) : [];
      d.mesh.forEach(function (m) {
        if (m[0] < box.latMin - 0.1 || m[0] > box.latMax + 0.1 || m[1] < box.lonMin - 0.1 || m[1] > box.lonMax + 0.1) return;
        var a = project(m[0] + MESH_DLAT / 2, m[1] - MESH_DLON / 2, size.width, size.height, box);
        var b = project(m[0] - MESH_DLAT / 2, m[1] + MESH_DLON / 2, size.width, size.height, box);
        var w = zoomed ? Math.max(1, b.x - a.x - 1) : Math.max(2.2, b.x - a.x);
        var h = zoomed ? Math.max(1, b.y - a.y - 1) : Math.max(2.2, b.y - a.y);
        var r = 'M' + (a.x + ox).toFixed(1) + ' ' + (a.y + oy).toFixed(1) + 'h' + w.toFixed(1) + 'v' + h.toFixed(1) + 'h' + (-w).toFixed(1) + 'z';
        paths[bucket(m[2])] += r;
        if (selCells && selIds.indexOf(selCells[meshKey(m[0], m[1])]) >= 0) sel += r;
      });
      var outlines = '';
      if (state.index) {
        state.index.areas.forEach(function (ar) {
          if (ar.kind !== 'island') return;
          var bb = ar.bbox;
          var p = project(bb[1], bb[2], size.width, size.height, box), q = project(bb[0], bb[3], size.width, size.height, box);
          if (q.x < 0 || p.x > size.width || q.y < 0 || p.y > size.height) return;
          var on = selIds.indexOf(ar.id) >= 0;
          outlines += '<rect class="fd-map__isle' + (on ? ' is-on' : '') + '" x="' + (p.x + ox).toFixed(1) + '" y="' + (p.y + oy).toFixed(1) +
            '" width="' + Math.max(3, q.x - p.x).toFixed(1) + '" height="' + Math.max(3, q.y - p.y).toFixed(1) + '"></rect>';
        });
      }
      svg.innerHTML = outlines + paths.map(function (p, i) { return '<path class="fd-map__b' + i + '" d="' + p + '"/>'; }).join('') +
        (sel ? '<path class="fd-map__sel" d="' + sel + '"/>' : '');
    }
    function pointer(e) {
      var r = svg.getBoundingClientRect();
      var x = e.clientX - r.left, y = e.clientY - r.top;
      var ll = unproject(x - geom.ox, y - geom.oy, geom.size.width, geom.size.height, geom.box);
      return { x: x, y: y, lat: ll.lat, lon: ll.lon, w: r.width };
    }
    function areaById(id) { return state.index.areas.filter(function (a) { return a.id === id; })[0]; }
    svg.addEventListener('mousemove', function (e) {
      if (!geom) return;
      var p = pointer(e);
      var m = cells[meshKey(p.lat, p.lon)];
      var aid = state.index ? areaAt(p.lat, p.lon, state.index) : null;
      var area = aid && areaById(aid);
      if (!m && !area) { tip.hidden = true; svg.style.cursor = 'default'; return; }
      svg.style.cursor = area ? 'pointer' : 'default';
      var txt = m ? t('square') + ' · ' + fmtInt(m[2]) + ' ' + t('records') + ' · ' + fmtInt(m[3]) + ' ' + t('species') : '';
      if (area) txt += (txt ? ' — ' : '') + t('clickHint') + ': ' + (lang === 'ja' ? area.name_ja : area.name_en);
      tip.hidden = false;
      tip.textContent = txt;
      tip.style.left = Math.max(0, Math.min(p.x + 12, p.w - 300)) + 'px';
      tip.style.top = Math.max(0, p.y - 34) + 'px';
    });
    svg.addEventListener('mouseleave', function () { tip.hidden = true; });
    svg.addEventListener('click', function (e) {
      if (!geom || !state.index) return;
      var p = pointer(e);
      var aid = areaAt(p.lat, p.lon, state.index);
      if (aid) selectArea(aid);
    });
    map.draw = draw;
    draw();
    if (root.ResizeObserver) { var ro = new root.ResizeObserver(draw); ro.observe(fig); }
    $('fd-map-cells').textContent = fmtInt(d.mesh.length);
    $('fd-masked').textContent = fmtInt(d.totals.sensitive_species);
  }

  /* ---------------------------------------------------------------- area drill-down */
  var base = '';
  function areaUrl(id) { return base + 'areas/' + encodeURIComponent(id) + '.json'; }

  function setupPicker() {
    var sel = $('fd-area-pick');
    var areas = state.index.areas.slice();
    var nm = function (a) { return lang === 'ja' ? a.name_ja : a.name_en; };
    var groups = areas.filter(function (a) { return a.kind === 'group'; }).sort(function (a, b) { return a.bbox[0] - b.bbox[0]; });
    var isles = areas.filter(function (a) { return a.kind === 'island'; }).sort(function (a, b) { return a.bbox[0] - b.bbox[0]; });
    var opt = function (a) { return '<option value="' + esc(a.id) + '">' + esc(nm(a)) + ' (' + fmtInt(a.species) + ' ' + esc(t('species')) + ')</option>'; };
    sel.innerHTML = '<option value="">' + esc(lang === 'ja' ? '地域を選ぶ（または地図をクリック）' : 'Choose an area, or click the map') + '</option>' +
      '<optgroup label="' + esc(lang === 'ja' ? '島しょ群' : 'Island groups') + '">' + groups.map(opt).join('') + '</optgroup>' +
      '<optgroup label="' + esc(lang === 'ja' ? '島' : 'Islands') + '">' + isles.map(opt).join('') + '</optgroup>';
    sel.addEventListener('change', function () { if (sel.value) selectArea(sel.value); else clearArea(); });
    $('fd-area-back').addEventListener('click', clearArea);
    doc.querySelectorAll('[data-fd-kind]').forEach(function (b) {
      b.addEventListener('click', function () { state.kind = b.getAttribute('data-fd-kind'); renderArea(); });
    });
    $('fd-month').innerHTML = '<button type="button" data-fd-month="0">' + (lang === 'ja' ? '全月' : 'All') + '</button>' +
      MONTHS_EN.map(function (_, i) { return '<button type="button" data-fd-month="' + (i + 1) + '">' + esc(monthName(i + 1, lang)) + '</button>'; }).join('');
    doc.querySelectorAll('[data-fd-month]').forEach(function (b) {
      b.addEventListener('click', function () { state.month = +b.getAttribute('data-fd-month'); renderArea(); });
    });
    $('fd-picker').hidden = false;
    var hash = (root.location.hash || '').slice(1);
    if (hash.indexOf('area-') === 0) selectArea(hash.slice(5));
  }

  function selectArea(id) {
    var status = $('fd-area-status');
    var go = function (a) {
      state.area = a;
      state.box = zoomBox(a.bbox);
      $('fd-area-pick').value = a.id;
      $('fd-area').hidden = false;
      $('fd-area-back').hidden = false;
      status.hidden = true;
      try { root.history.replaceState(null, '', '#area-' + a.id); } catch (e) { /* ignore */ }
      if (map.draw) map.draw();
      renderArea();
    };
    if (state.cache[id]) return go(state.cache[id]);
    root.fetch(areaUrl(id), { cache: 'no-cache' })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (a) { state.cache[id] = a; go(a); })
      .catch(function () { status.hidden = false; status.textContent = t('areaError'); });
  }

  function clearArea() {
    state.area = null;
    state.box = JAPAN_BOX;
    $('fd-area').hidden = true;
    $('fd-area-back').hidden = true;
    $('fd-area-pick').value = '';
    try { root.history.replaceState(null, '', root.location.pathname); } catch (e) { /* ignore */ }
    if (map.draw) map.draw();
  }

  function monthStrip(m, hi) {
    var max = Math.max.apply(null, m) || 1;
    return '<span class="fd-ms" aria-hidden="true">' + m.map(function (v, i) {
      return '<i class="' + (v ? 'on' : '') + (hi === i + 1 ? ' hi' : '') + '" style="--v:' + (v ? (0.35 + 0.65 * v / max).toFixed(2) : 0) + '"></i>';
    }).join('') + '</span><span class="fd-sr">' + m.map(function (v, i) { return v ? monthName(i + 1, lang) : ''; }).filter(Boolean).join(', ') + '</span>';
  }

  function renderArea() {
    var a = state.area;
    if (!a) return;
    var tot = a.totals;
    $('fd-area-title').textContent = lang === 'ja' ? a.name_ja : a.name_en;
    var meta = [fmtInt(tot.records) + ' ' + t('records'), fmtInt(tot.species) + ' ' + t('species')];
    if (tot.squares) meta.push(fmtInt(tot.squares) + ' ' + t('squares'));
    if (tot.by_name) meta.push(fmtInt(tot.by_name) + ' ' + t('byName'));
    if (tot.unresolved) meta.push(fmtInt(tot.unresolved) + ' ' + t('unresolved'));
    $('fd-area-meta').textContent = meta.join(' · ');
    var note = samplingNote(a.top_localities, tot.records);
    $('fd-area-note').hidden = !note;
    if (note) $('fd-area-note').textContent = t('sampling') + ': ' + note.name + ' (' + note.share + '%).';
    doc.querySelectorAll('[data-fd-kind]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-fd-kind') === state.kind)); });
    doc.querySelectorAll('[data-fd-month]').forEach(function (b) { b.setAttribute('aria-pressed', String(+b.getAttribute('data-fd-month') === state.month)); });
    var mmax = Math.max.apply(null, a.months) || 1;
    $('fd-area-months').innerHTML = a.months.map(function (v, i) {
      return '<div class="fd-mbar' + (state.month === i + 1 ? ' is-on' : '') + '" title="' + fmtInt(v) + ' ' + esc(t('records')) + '"><span style="height:' +
        Math.max(2, (100 * v) / mmax).toFixed(0) + '%"></span><small>' + esc(monthName(i + 1, lang)) + '</small></div>';
    }).join('');

    var names = a.member_names || {};
    var list = filterSpecies(a.species, state.kind, state.month);
    $('fd-area-count').textContent = fmtInt(list.length);
    var head = [t('sp'), t('family'), t('rec'), t('months'), a.kind === 'group' ? t('islands') : t('where'), t('evidence')];
    $('fd-area-species').innerHTML = list.length ? '<thead><tr>' + head.map(function (h, i) { return '<th' + (i === 2 ? ' class="num"' : '') + '>' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>' +
      list.slice(0, 300).map(function (s) {
        var where = a.kind === 'group'
          ? (s.i || []).map(function (id) { return names[id] ? names[id][lang === 'ja' ? 1 : 0] : id; }).join(', ')
          : (s.h && s.h.length ? s.h : s.l || []).join(' / ');
        var ev = Object.keys(s.e || {}).map(function (k) { return T['ev_' + k] ? t('ev_' + k) : k; }).join(', ');
        return '<tr><td><a href="https://www.gbif.org/species/search?q=' + encodeURIComponent(s.n) + '" target="_blank" rel="noopener"><i>' + esc(s.n) + '</i></a></td><td>' +
          esc(s.f) + '</td><td class="num">' + fmtInt(s.r) + '</td><td>' + monthStrip(s.m, state.month) + '</td><td class="fd-where">' + esc(where) + '</td><td>' + esc(ev) + '</td></tr>';
      }).join('') + '</tbody>' : '<tbody><tr><td class="fd-empty">' + esc(t('noSpecies')) + '</td></tr></tbody>';

    var poss = filterSpecies(a.possible || [], state.kind, state.month);
    $('fd-poss-count').textContent = fmtInt(poss.length);
    var phead = [t('sp'), t('family'), t('likelihood'), t('nearest'), t('months')];
    $('fd-area-possible').innerHTML = poss.length ? '<thead><tr>' + phead.map(function (h) { return '<th>' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>' +
      poss.slice(0, 40).map(function (p) {
        return '<tr><td><a href="https://www.gbif.org/species/search?q=' + encodeURIComponent(p.n) + '" target="_blank" rel="noopener"><i>' + esc(p.n) + '</i></a></td><td>' +
          esc(p.f) + '</td><td><span class="fd-like" title="' + p.s + '/100"><span style="width:' + p.s + '%"></span></span></td><td class="fd-where">' + fmtInt(p.d) + ' ' + t('km') + ' · ' +
          esc(lang === 'ja' ? p.wj : p.w) + '</td><td>' + monthStrip(p.m, state.month) + '</td></tr>';
      }).join('') + '</tbody>' : '<tbody><tr><td class="fd-empty">' + esc(t('noPossible')) + '</td></tr></tbody>';
  }

  function renderLeads(d) {
    var head = lang === 'ja'
      ? ['種', '科', '近隣国の記録', 'MOの記録', '次の確認']
      : ['Species', 'Family', 'Records next door', 'Mushroom Observer', 'What to check'];
    var body = d.leads.map(function (l) {
      var url = 'https://www.gbif.org/species/search?q=' + encodeURIComponent(l[0]);
      return '<tr><td><a href="' + url + '" target="_blank" rel="noopener"><i>' + esc(l[0]) + '</i></a></td><td>' + esc(l[1] || '') +
        '</td><td class="num">' + fmtInt(l[2]) + '</td><td class="num">' + fmtInt(l[3]) + '</td><td>' + esc(triage(l[4], lang)) + '</td></tr>';
    }).join('');
    $('fd-leads').innerHTML = '<thead><tr>' + head.map(function (h) { return '<th>' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>' + body + '</tbody>';
    $('fd-lead-total').textContent = fmtInt(d.lead_totals.neighbour_only);
    $('fd-lead-mo').textContent = fmtInt(d.lead_totals.with_mo);
    $('fd-lead-unres').textContent = fmtInt(d.lead_totals.with_unresolved_jp_genus);
  }

  function renderSources(d) {
    $('fd-sources').innerHTML = d.sources.map(function (s) {
      return '<li><a href="https://doi.org/' + esc(s.doi) + '" target="_blank" rel="noopener">doi.org/' + esc(s.doi) + '</a> · ' +
        fmtInt(s.records) + ' ' + t('records') + ' · ' + t('downloaded') + ' ' + esc(String(s.created || '').slice(0, 10)) + '</li>';
    }).join('');
    $('fd-generated').textContent = d.generated;
  }

  function render(d) {
    state.d = d;
    renderKpis(d);
    setupMap(d);
    $('fd-evidence').innerHTML = barRows(d.evidence.slice(0, 5), d.totals.records, function (k) { return label(k, lang); });
    $('fd-depth').innerHTML = barRows(d.id_depth, d.totals.records, function (k) { return label(k, lang); });
    $('fd-decades').innerHTML = barRows(d.decades.filter(function (r) { return r[0] >= 1950; }).reverse(), 0,
      function (y) { return lang === 'ja' ? y + '年代' : y + 's'; });
    $('fd-unresolved').innerHTML = barRows(d.unresolved_genera.slice(0, 10).map(function (g) { return [g[0], g[2]]; }), 0,
      function (g) { return g; });
    $('fd-unresolved').querySelectorAll('.fd-bar__label').forEach(function (el) { el.style.fontStyle = 'italic'; });
    renderLeads(d);
    renderSources(d);
    doc.querySelector('.fd').classList.add('is-ready');
  }

  function start() {
    var el = doc.querySelector('.fd');
    if (!el) return;
    var src = el.getAttribute('data-src');
    base = src.slice(0, src.lastIndexOf('/') + 1);
    root.fetch(src, { cache: 'no-cache' })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (d) { if (!isValid(d)) throw new Error('invalid data'); render(d); })
      .then(function () { return root.fetch(base + 'areas/index.json', { cache: 'no-cache' }); })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (ix) { state.index = ix; setupPicker(); if (map.draw) map.draw(); })
      .catch(function () {
        if (!state.d) { $('fd-status').hidden = false; $('fd-status').textContent = t('loadError'); }
      });
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', start); else start();
})(typeof window !== 'undefined' ? window : this);
